class Solution {
  public int countComponents(int n, int[][] edges) {
    int[] parent = new int[n];
    for (int i = 0; i < n; i++) parent[i] = i;
    int components = n;
    for (int[] e : edges) {
      int a = find(parent, e[0]), b = find(parent, e[1]);
      if (a != b) {
        parent[a] = b;
        components--;
      }
    }
    return components;
  }

  private int find(int[] p, int x) {
    while (p[x] != x) x = p[x] = p[p[x]];
    return x;
  }
}
